var e={"term.setting":`代码模式`,"term.settingDesc":`用于和 Claude 一起写代码：每个会话一个独立副本（有自己的分支和文件夹，以 Claude 编写并监视的拉取请求收尾），以及对话下方的终端（Ctrl+J、/terminal），在会话的 git 仓库中打开。每次回答的更改（diff、commit、push、拉取请求）和拉取请求视图无需此模式也会显示。不适用于智能体。开启时需要输入密码。`,"term.enableTitle":`开启代码模式`,"term.enableDesc":`代码模式会添加一个终端，可以用本服务器的权限运行任意命令，并为会话提供仓库的独立副本。请输入密码确认。`,"term.password":`密码`,"term.badPassword":`密码错误`,"term.enable":`开启`,"term.openFailed":`终端未能打开`,"term.tooMany":`已打开 4 个终端：请先关闭一个`,"term.close":`关闭此终端`,"term.new":`新建终端`,"term.quote":`将所选内容发送给 Claude`,"term.openCount":`已打开 {count} 个`,"term.openCount#one":`已打开 {count} 个`,"term.closeAll":`全部关闭`,"term.hide":`隐藏终端`,"term.opening":`正在打开…`,"term.ended":`[终端已结束]`,"term.topicFolder":`主题文件夹`};export{e as default};